def card(work):
    codebook = {'COST': 'mentions price or expense', 'TRUST': 'mentions reliability or honesty', 'TIME': 'mentions waiting or speed'}
    excerpts = [('int1:L4', 'Too expensive for us'), ('int1:L9', 'They always deliver on time'), ('int2:L2', 'I trust their reviews'), ('int2:L7', 'The wait was long'), ('int3:L1', 'Price went up again'), ('int3:L5', 'Fast replies'), ('int4:L3', 'Honest staff'), ('int4:L8', 'Costs too much'), ('int5:L2', 'Slow checkout'), ('int5:L6', 'I rely on them')]
    coder_a = ['COST', 'TIME', 'TRUST', 'TIME', 'COST', 'TIME', 'TRUST', 'COST', 'TIME', 'TRUST']
    coder_b = ['COST', 'TRUST', 'TRUST', 'TIME', 'COST', 'TIME', 'TRUST', 'COST', 'COST', 'TRUST']
    k = cohen_kappa(coder_a, coder_b)
    claims = ['Higher prices lead to churn', 'Customers who mention trust also mention speed']
    kinds = ['causal' if CAUSAL.search(c) else 'associational' for c in claims]
    rivals = {claims[0]: ['seasonal demand drop', 'competitor launch']}
    out = {'codebook': codebook, 'coded': [{'ref': r, 'text': t, 'a': x, 'b': y} for (r, t), x, y in zip(excerpts, coder_a, coder_b)], 'kappa': round(k, 4), 'claims': dict(zip(claims, kinds)), 'rivals': rivals}
    save(work, 'coding.json', out)
    return [eq('Cohen kappa', round(k, 4), round(0.48 / 0.68, 4)), truth('every coded excerpt keeps its source reference', all((':' in c['ref'] for c in out['coded']))), eq('claim types', kinds, ['causal', 'associational']), truth('causal claim lists rival explanations', len(rivals[claims[0]]) >= 2)]

