def card(work):
    ok = patent_intake({'q1': ['an app that does stuff', 'solar panel cleaning drone using electrostatic dust repulsion on desert farms'], 'q2': 'freedom-to-operate', 'q3': ['US', 'EP']})
    errs = []
    for bad in ({'q1': ['x ' * 9], 'q2': 'general', 'q3': ['US']}, {'q1': ['y ' * 9], 'q2': 'novelty', 'q3': ['XX']}):
        try:
            patent_intake(bad)
        except ValueError as e:
            errs.append(str(e))
    save(work, 'patent_intake.json', {'ok': ok, 'errors': errs})
    return [eq('vague Q1 rejected once', len(ok['log']), 1), truth('precise description accepted', ok['description'].startswith('solar panel')), truth('concept keywords extracted', {'electrostatic', 'drone', 'solar'} <= set(ok['keywords']), ok['keywords']), eq('bad sub-use-case and jurisdiction refused', len(errs), 2), truth('no-legal-advice caveat', 'not legal advice' in ok['caveat'])]
